typedef struct { size_t i, n; const Item *src; } RangeGen;

void range_init(RangeGen *g, const Item *src, size_t n) {
    g->src = src; g->n = n; g->i = 0;
}

bool range_next(RangeGen *g, Item *out) {
    if (g->i >= g->n) return false;   /* exhausted: keep returning false */
    *out = g->src[g->i++];            /* exactly one element per call */
    return true;
}
