typedef struct { ucontext_t self, caller; } Gen;

static void produce(uintptr_t arg) {     /* runs on its own stack */
    Gen *g = (Gen *)arg;
    for (int i = 0; i < 10; i++) {       /* straight-line producer */
        yield_to_caller(g, i);           /* swapcontext + value hand-off */
    }
}
